#!/usr/bin/bash
# Container side of the ISO build (generated by
# rakuos-project/github-workflow-gen/iso/gen.py; edit the template there).
# Runs as root in quay.io/fedora/fedora:latest, privileged, from run-iso.sh.
# The same steps as the GitLab job build-iso-standard.
set -euo pipefail

dnf install -y -q git podman jq curl findutils tar openssh-clients sshpass awscli

case "${BRANCH}" in
  main)    BRANCH_SLUG=latest;  IS_STABLE=true ;;
  staging) BRANCH_SLUG=staging; IS_STABLE=false ;;
  *)       BRANCH_SLUG="$(printf '%s' "${BRANCH}" | tr '[:upper:]' '[:lower:]' | sed 's#[^a-z0-9._-]#-#g')"; IS_STABLE=false ;;
esac
BUILD_DATE="$(date -u +%Y.%m.%d)"
PLATFORM=amd64
IMAGE_REF="${IMAGE_REPO}:${BRANCH_SLUG}"
echo "Building the ${EDITION} ISO from ${IMAGE_REF}"

rpm --import https://repo.rakuos.org/pubkey.gpg
dnf -y config-manager addrepo --from-repofile=https://repo.rakuos.org/rakuos.repo
dnf install -y rakuos-forge
export RAKUFORGE_BUILDER_DISTRO=fedora
export HOOK_post_rootfs="${PWD}/config/configure-iso.sh"
export HOOK_pre_initramfs="${PWD}/config/pre_initramfs.sh"

if [[ "${FORGE_MODE}" == "minimal" ]]; then
  # The minimal ISO: its live system is the minimal image with a KDE session
  # layered on by config/configure-iso.sh, plus a text-mode installer entry.
  if [[ "${BRANCH_SLUG}" == "latest" ]]; then
    PRETTY_NAME="RakuOS Minimal"
  else
    PRETTY_NAME="RakuOS ${BRANCH_SLUG} Minimal"
  fi
  rakuos-forge build "${IMAGE_REF}" --compression erofs --livesys true --cli-installer true --pretty-name "${PRETTY_NAME}"
else
  rakuos-forge build "${IMAGE_REF}" --compression erofs --container-image "${IMAGE_REF}"
fi

mkdir -p output
if [[ "${IS_STABLE}" == "true" ]]; then
  NEW_ISO_NAME="rakuos-${EDITION}-${BUILD_DATE}-${PLATFORM}.iso"
  LATEST_ISO_NAME="rakuos-${EDITION}-latest-${PLATFORM}.iso"
else
  NEW_ISO_NAME="rakuos-${EDITION}-${BRANCH_SLUG}-${BUILD_DATE}-${PLATFORM}.iso"
  LATEST_ISO_NAME="rakuos-${EDITION}-${BRANCH_SLUG}-latest-${PLATFORM}.iso"
fi
[[ -f output.iso ]] || { echo "ERROR: ISO output not found"; ls -la; exit 1; }
mv output.iso "output/${NEW_ISO_NAME}"
sha256sum "output/${NEW_ISO_NAME}" > "output/${NEW_ISO_NAME}.sha256"
cp "output/${NEW_ISO_NAME}" "output/${LATEST_ISO_NAME}"
sha256sum "output/${LATEST_ISO_NAME}" > "output/${LATEST_ISO_NAME}.sha256"

if [[ "${CDN77_UPLOAD}" == "true" ]] && { [[ "${IS_STABLE}" == "true" ]] || [[ "${BRANCH_SLUG}" == "staging" ]]; }; then
  echo "Purging CDN77 cache for ${CDN77_PATH}/${LATEST_ISO_NAME}..."
  curl -fsS -X POST "https://api.cdn77.com/v3/cdn/${CDN77_CDN_ID}/job/purge/paths" \
    -H "Authorization: Bearer ${CDN77_API_KEY}" -H "Content-Type: application/json" \
    -d "{\"paths\": [\"/${CDN77_PATH}/${LATEST_ISO_NAME}\", \"/${CDN77_PATH}/${LATEST_ISO_NAME}.sha256\"]}" || true
  sleep 120
  # A cancelled earlier upload can leave a multipart upload behind that makes
  # CDN77 reject the next one ("already in progress"): abort those first.
  AWS_ACCESS_KEY_ID="${CDN77_ACCESS_KEY}" AWS_SECRET_ACCESS_KEY="${CDN77_SECRET_KEY}" \
    aws s3api list-multipart-uploads --bucket "${CDN77_BUCKET}" --prefix "${CDN77_PATH}/${LATEST_ISO_NAME}" \
      --endpoint-url "${CDN77_ENDPOINT_URL}" --query "Uploads[].UploadId" --output text 2>/dev/null \
    | tr '\t' '\n' | while read -r upload_id; do
        [[ -z "${upload_id}" || "${upload_id}" == "None" ]] && continue
        AWS_ACCESS_KEY_ID="${CDN77_ACCESS_KEY}" AWS_SECRET_ACCESS_KEY="${CDN77_SECRET_KEY}" \
          aws s3api abort-multipart-upload --bucket "${CDN77_BUCKET}" --key "${CDN77_PATH}/${LATEST_ISO_NAME}" \
            --upload-id "${upload_id}" --endpoint-url "${CDN77_ENDPOINT_URL}" || true
      done
  cdn77_upload() {
    local src="$1" dest="$2" attempt=1
    until AWS_ACCESS_KEY_ID="${CDN77_ACCESS_KEY}" AWS_SECRET_ACCESS_KEY="${CDN77_SECRET_KEY}" \
        aws s3 cp "${src}" "s3://${CDN77_BUCKET}/${dest}" --endpoint-url "${CDN77_ENDPOINT_URL}" --no-progress; do
      [[ "${attempt}" -ge 5 ]] && { echo "CDN77 upload of ${dest} failed after ${attempt} attempts."; return 1; }
      echo "CDN77 upload of ${dest} failed (attempt ${attempt}/5), retrying in 20s..."
      attempt=$((attempt + 1)); sleep 20
    done
  }
  echo "Uploading to CDN77 (dl.rakuos.org/${CDN77_PATH})..."
  cdn77_upload "output/${LATEST_ISO_NAME}" "${CDN77_PATH}/${LATEST_ISO_NAME}"
  cdn77_upload "output/${LATEST_ISO_NAME}.sha256" "${CDN77_PATH}/${LATEST_ISO_NAME}.sha256"
else
  echo "CDN77 upload disabled or not main/staging; skipping."
fi

if [[ "${SOURCEFORGE_UPLOAD}" == "true" ]]; then
  sshpass -p "${SOURCEFORGE_PASSWORD}" scp -o StrictHostKeyChecking=no \
    "output/${LATEST_ISO_NAME}" "${SOURCEFORGE_USERNAME}@${SOURCEFORGE_HOST}:${SOURCEFORGE_LATEST_PATH}/${LATEST_ISO_NAME}"
  sshpass -p "${SOURCEFORGE_PASSWORD}" scp -o StrictHostKeyChecking=no \
    "output/${NEW_ISO_NAME}" "${SOURCEFORGE_USERNAME}@${SOURCEFORGE_HOST}:${SOURCEFORGE_ARCHIVE_ROOT}/${SOURCEFORGE_DIR}/${NEW_ISO_NAME}"
else
  echo "SourceForge upload disabled; skipping."
fi
